SELECT CASE WHEN temp_c >= 33.4 THEN 'HIGH' ELSE 'LOW' END AS temp_c_tier, CASE WHEN status_bits >= 10 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, CASE WHEN pressure >= 1018 THEN 'PREMIUM' ELSE 'STANDARD' END AS pressure_tier, COUNT(DISTINCT firmware) AS distinct_firmwares, COUNT_IF(device_code = 'DV-04') AS dv_04_events, SUM(temp_c) FILTER (WHERE device_code = 'DV-04') AS dv_04_total_temp_c, MAX(status_bits) AS max_status_bits, COUNT(DISTINCT firmware) AS distinct_firmwares_2, BIT_AND(status_bits) AS status_bits_bit_and FROM device_readings GROUP BY CASE WHEN temp_c >= 33.4 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN status_bits >= 10 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN pressure >= 1018 THEN 'PREMIUM' ELSE 'STANDARD' END;
